import{_ as i,l as n,o as e,c as r,v as o,p as d,x as l,d as m,i as s,S as p}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"Dolma 原文","description":"","frontmatter":{"title":"Dolma 原文","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/dolma-paper.md","filePath":"llm/dolma-paper.md","lastUpdated":1789023840000}'),B={name:"llm/dolma-paper.md"};function h(c,a,E,u,D,b){const t=n("Mermaid");return e(),r("div",null,[a[1]||(a[1]=o('<h1 id="dolma-原文" tabindex="-1">Dolma 原文 <a class="header-anchor" href="#dolma-原文" aria-label="Permalink to &quot;Dolma 原文&quot;">​</a></h1><div class="epigraph"><p>闭源模型几乎不谈预训练数据，开源模型也常常只给权重；没有语料与工具链，就无法把「数据如何塑造能力」当成可重复的科学问题。</p><footer>—— Soldaini et al., Dolma: an Open Corpus of Three Trillion Tokens for Language Model Pretraining Research, 2024</footer></div><p>Soldaini 等人把 Data for Open Language Models&#39; Appetite 收成约三万亿英语 token 的公开混合物，并同时开源高速处理工具链。来源刻意贴近已知的工业配方：Common Crawl 网页、Semantic Scholar 论文、GitHub 代码、公有领域书籍、Reddit、维基百科与 Wikibooks。原稿对应 Dolma v1.6：从约 200TB 原始文本收到 11TB，Llama tokenizer 下约 3.06T token，其中网页约 2.48T、代码 411B、社交 89B、论文 70B、书籍 6B、百科 4.3B。它是 OLMo 的预训练底座，也是此后所有「可治理多源语料」讨论的参照实现——不是声称每桶都是当时最强过滤，而是声称每一步都可以被复现、替换与问责。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>2023–2024 年最强的模型把数据当成商业秘密。GPT-4、PaLM 2、Claude 几乎不报来源；Llama 2、Mistral、Qwen 开权重却不开语料。结果是双重失灵：应用方无法判断模型在哪些领域该被信任，研究方无法做记忆、去重、污染、归因这类必须看见训练字节的工作。C4 与 The Pile 质量公认，但规模停在千亿；ROOTS 大而英语太少；Falcon 的公开网页与 RedPajama V2 够大，却几乎只有 Crawl；RedPajama V1 最接近多源理想，却被 Soboleva 与 Elazar 等人指出重复与质量问题，且缺科学论文与论坛的更大集合。</p><p>Dolma 要同时满足四条有张力的目标。与既有配方一致，以便结论能外推到闭源模型；拿不准时用 1.2B OLMo 消融、在多样下游上选边；规模到 2–3T，好让人研究 Chinchilla 之后「继续加 token」的区间；以及真正的开放——数据可下载、过程可文档化。最后一条会逼你偏离 LLaMA：Books3 因诉讼不能收，PII 尽管旧配方很少谈也必须做。问题因而不是「如何堆出最大的网页」，而是「在可发布约束下，如何得到一张与工业混合物同构、又经得起审计的来源图」。</p><h3 id="开放会改写配方本身" tabindex="-1">开放会改写配方本身 <a class="header-anchor" href="#开放会改写配方本身" aria-label="Permalink to &quot;开放会改写配方本身&quot;">​</a></h3><p>避 Books3、做 PII、给每源单独的许可与毒性策略，都会让 Dolma 不再是 LLaMA 的比特级影子。这不是缺陷。Soldaini 等人把这类偏离写成一等原则：开放优先于盲从。Reddit 与论文 HTML 进入混合物，是因为它们在已知配方里出现、且可以合法发布；不是因为消融证明它们是最优正例。<span class="marginnote">数据卡片上的 token 比例是治理工具，不是因果效应。网页仍占八成以上，百科只有约 4B。任何「Dolma 很全面」的说法，都必须先承认它仍然是一个网页主导、英语主导的语料，多样性来自尾部的论文与代码，而不是均匀的六分天下。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>工具链把操作收成两类。过滤：给定文本单元（文档、段落、句子）、打分器（分类器、困惑度、正则）和处置（删除或替换），在数百 TB 上并行执行。混合：跨文件做上/下采样、去重与去污，Rust 实现；Bloom 过滤器做线性时间的概率重复检测，也可先灌入评测集再在训练集上标记污染。内部复现 C4 时，过滤速度约每 TB 122 CPU 小时。单元测试级别的「质量」「毒性」在文中被明确警告：这两个词是意识形态与标注者身份的函数，不是中性物理量。</p><p>网页支路走 CCNet 风格：语言识别、启发式质量、去重，再叠毒性与 PII。代码来自 GitHub 许可友好子集；论文用 Semantic Scholar 的 peS2o；书籍限 Gutenberg 一类公有领域；社交是 Reddit；百科是维基家族。每一源有自己的入口规则，混合物的字节与 token 写在表 1。消融用 1.2B 解码器、训到 150B token 就停，为的是在可承受的预算下比较「干预 vs 基线」，而不是把每个决定训到收敛。这与 FineWeb 后来在 1.8B、28B/350B token 上做的数据消融是同一方法论，只是 Dolma 还要在来源之间做混合，不只在网页内做过滤。</p>',11)),(e(),d(p,null,{default:l(()=>[s(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20RAW%5B%22%E7%BA%A6%20200TB%20%E5%8E%9F%E5%A7%8B%E6%96%87%E6%9C%AC%22%5D%20--%3E%20FIL%5B%22%E8%BF%87%E6%BB%A4%EF%BC%9A%E8%AF%AD%E8%A8%80%20%2F%20%E8%B4%A8%E9%87%8F%20%2F%20%E6%AF%92%E6%80%A7%20%2F%20PII%22%5D%0A%20%20FIL%20--%3E%20MIX%5B%22%E6%B7%B7%E5%90%88%EF%BC%9A%E9%87%87%E6%A0%B7%E3%80%81%E5%8E%BB%E9%87%8D%E3%80%81%E5%8E%BB%E6%B1%A1%22%5D%0A%20%20CC%5B%22Common%20Crawl%22%5D%20--%3E%20FIL%0A%20%20GH%5B%22GitHub%22%5D%20--%3E%20FIL%0A%20%20RD%5B%22Reddit%22%5D%20--%3E%20FIL%0A%20%20SS%5B%22Semantic%20Scholar%22%5D%20--%3E%20FIL%0A%20%20GB%5B%22Gutenberg%22%5D%20--%3E%20FIL%0A%20%20WK%5B%22Wikipedia%22%5D%20--%3E%20FIL%0A%20%20MIX%20--%3E%20DOL%5B%22Dolma%20~3T%20token%22%5D%0A%20%20DOL%20--%3E%20OL%5B%22OLMo%20%E9%A2%84%E8%AE%AD%E7%BB%83%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[m(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h3 id="中间状态比最终快照更重要" tabindex="-1">中间状态比最终快照更重要 <a class="header-anchor" href="#中间状态比最终快照更重要" aria-label="Permalink to &quot;中间状态比最终快照更重要&quot;">​</a></h3><p>论文花大量篇幅报告「砍掉这一刀之后下游怎样」，而不是只给最终 tar 包。这是它相对纯数据集发布的增量：读者可以看到语言门、重复门、PII 门各自移动了哪些探针。Bloom 去重同时服务两件事——降记忆、防训练集抄评测。上采样通过对同一路径多次读取实现，避免先物理复制再训练。工具链的意义是：下一次 Crawl 到来时，你可以重跑规则，而不是永远依赖 v1.6 的字节。</p><p><span class="marginnote">手稿写明针对 v1.6，并预告会继续改。后来的 v1.7 增加 OpenWebMath、Flan、StarCoder 代码并收紧网页过滤，配比与 3T 全量都变了。引用 Dolma 必须写版本。OLMo 1.7 的二阶段甚至在子集上再平衡，那已经是训练课表，不是语料默认分布。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>多源开放语料改变的是研究的可识别性。记忆实验需要知道某串字符是否在训练集；污染分析需要把评测 n-gram 打进 Bloom；归因需要来源标签。闭源混合物把这些实验关在实验室门外。Dolma 用文档级来源字段把 \\(p(d)=\\sum_s w_s p_s(d)\\) 变成可检验的对象：你可以丢掉论文桶再训一遍，问 MMLU 掉多少。网页仍主导，所以「来源多样」主要影响尾部能力（代码补全、引用风格、论坛口语），头部的英语阅读仍由 Crawl 过滤质量决定。</p><p>过滤与混合的分工接近 RefinedWeb 之后的共识。过滤改支撑，混合改权重。跨源去重特别关键：同一篇预印本以 HTML 出现在网页、以 PDF 解析出现在 peS2o、以维基摘要出现在百科。若只在桶内去重，配比表是假的。Bloom 有假阳性，会误伤合法长尾；假阴性则留下转载。Soldaini 等人接受概率结构，是因为确定性后缀数组在 11TB 上的工程成本更高——这是与 RefinedWeb 精确子串不同的取舍。</p><h3 id="与-redpajama、fineweb-的位置" tabindex="-1">与 RedPajama、FineWeb 的位置 <a class="header-anchor" href="#与-redpajama、fineweb-的位置" aria-label="Permalink to &quot;与 RedPajama、FineWeb 的位置&quot;">​</a></h3><p>相对 RedPajama V1，Dolma 加大论文与社交、避开 Books3、把工具链当一等公民，并承认 V1 需要额外清理。相对 FineWeb，Dolma 不把网页做到 15T 的极致纯度，而是保持多源治理；FineWeb 回答「单源网页还能多强」，Dolma 回答「开放混合物如何被科学使用」。二者应并列引用，而不是互相替代。OLMo 证明这份语料能训出可完全复现的基座；它没有证明三万亿是计算最优，也没有证明英语网页八成的配比适合你的产品。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>英语范围是方法选择，也是偏见来源。作者写明希望未来扩语种，并放出工具链作为承诺。Reddit 与网页的毒性过滤依赖有争议的分类器，可能误删少数群体自我指涉、放过礼貌的错误信息。PII 正则抓电话与邮箱，抓不住间接标识。Gutenberg 的书籍桶太小，长篇叙事能力不能指望它。GitHub 桶随后在 v1.7 被 StarCoder 集合替换，说明 v1.6 的代码质量并不是终点。</p><p>150B token 的消融会低估只在万亿级才出现的数据效应，例如长尾知识与污染。把消融赢家直接放大到 7B、3T，需要 OLMo 全量训练来背书，而全量训练又引入优化器与课表变量。开放许可（ODC-By）覆盖数据集，不自动覆盖每条网页的原始站点条款——使用时仍要自己看来源。工具链能复现规则，不能复现已经消失的 URL 与修订后的 Reddit 快照。</p><p><span class="marginnote">「用了 Dolma」若只下载预构建 parquet、不记录过滤配置与版本哈希，下一批数据到来时你并没有配方。论文把 toolkit 写成贡献，就是在反对这种用法。快照服务训练，规则服务研究。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Dolma v1.6 是约 3T token 的英语多源公开语料，服务 OLMo 与可重复的预训练研究。</li><li>六源为网页、代码、Reddit、论文、Gutenberg、维基；网页仍占绝大多数 token。</li><li>工具链把过滤与混合做成可配置操作，Bloom 用于去重与去污。</li><li>设计原则是贴近已知配方、用消融拍板、规模够大、开放优先（故避开 Books3、加入 PII）。</li><li>版本必须写明；v1.7 改了来源与网页过滤，不能与 v1.6 混报。</li><li>它提供可审计的混合物，不提供单桶最强网页；后者见 Penedo 的 FineWeb。</li><li>出处：Soldaini et al.，<em>Dolma: an Open Corpus of Three Trillion Tokens for Language Model Pretraining Research</em>，arXiv:2402.00159，2024；对照 Together RedPajama、Penedo FineWeb、Groeneveld et al. OLMo。</li></ul>',14))])}const P=i(B,[["render",h]]);export{A as __pageData,P as default};
